    pub(crate) fn check_media_speech(&self, media: &Media) -> Result<(), String> {
        let Some(spans) = &media.speech else {
            return Ok(());
        };
        let id = media.id;
        if !media.has_audio {
            return Err(format!(
                "media {id} has no audio, so it has no speech to duck by"
